def is_valid_trie(trie):
    """
    Checks if a trie is valid. A valid trie is a trie where each node has a value of 0 or 1.
    """
    def is_leaf(node):
        return node.value == 0 or node.value == 1

    def is_trie_valid(trie):
        if not trie:
            return True
        if is_leaf(trie.root):
            return True
        for child in trie.children:
            if not is_trie_valid(trie.children[child]):
                return False
        return True

    return is_trie_valid(trie)
